def normalize(s):
    if not s:
        return ""
    s = str(s).lower().strip()
    result = ""
    for ch in s:
        if ch.isalnum():
            result += ch
    return result

def levenshtein_ratio(a, b):
    a, b = str(a).lower().strip(), str(b).lower().strip()
    if a == b:
        return 1.0
    len_a, len_b = len(a), len(b)
    if len_a == 0 or len_b == 0:
        return 0.0
    prev_row = list(range(len_b + 1))
    for i in range(1, len_a + 1):
        curr_row = [i] + [0] * len_b
        for j in range(1, len_b + 1):
            cost = 0 if a[i-1] == b[j-1] else 1
            curr_row[j] = min(prev_row[j] + 1, curr_row[j-1] + 1, prev_row[j-1] + cost)
        prev_row = curr_row
    distance = prev_row[len_b]
    return 1 - (distance / max(len_a, len_b))

