classification_batches = []
original_pairs = []

for item in _items:
    row = item['json']
    if 'output' in row:
        classification_batches.append(row['output'])
    elif 'pair_id' in row and 'inspiration_record' in row:
        original_pairs.append(row)

classification_lookup = {}
for batch in classification_batches:
    for c in batch:
        classification_lookup[c['pair_id']] = c

results = []
for pair in original_pairs:
    c = classification_lookup.get(pair['pair_id'])
    if c is None:
        continue
    combined = dict(pair)
    combined['is_same_depot'] = c['is_same_depot']
    combined['classification'] = c['classification']
    combined['reasoning'] = c['reasoning']
    results.append(combined)

return [{'json': r} for r in results]
